package co.edu.cinematch.core.service;
import co.edu.cinematch.core.exception.*;import co.edu.cinematch.core.model.*;import co.edu.cinematch.core.repository.*;import java.util.*;
public class FuncionService {private final Repository<Funcion> repo;private final PeliculaService peliculas;private final CineService cines;public FuncionService(Repository<Funcion>r,PeliculaService p,CineService c){repo=r;peliculas=p;cines=c;}public Funcion crear(Funcion f){validar(f);peliculas.buscar(f.getPeliculaId());cines.buscarSala(f.getSalaId());return repo.save(f);}public Funcion buscar(String id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Función",id));}public List<Funcion> listar(){return repo.findAll();}public List<Funcion> porPelicula(String peliculaId){peliculas.buscar(peliculaId);List<Funcion>r=new ArrayList<>();for(Funcion f:repo.findAll())if(peliculaId.equals(f.getPeliculaId()))r.add(f);return r;}public Funcion actualizar(String id,Funcion d){validar(d);Funcion f=buscar(id);f.setFechaFuncion(d.getFechaFuncion());f.setHoraInicio(d.getHoraInicio());f.setHoraFin(d.getHoraFin());f.setPrecio(d.getPrecio());f.setFormato(d.getFormato());f.setTipoFuncion(d.getTipoFuncion());return repo.save(f);}public void cancelar(String id){if(!repo.deleteById(id))throw new ResourceNotFoundException("Función",id);}private void validar(Funcion f){if(f==null)throw new ValidationException("La función no puede ser nula.");if(f.getPrecio()<=0)throw new ValidationException("El precio debe ser mayor a 0.");if(f.getHoraInicio()==null||f.getHoraFin()==null||!f.getHoraFin().isAfter(f.getHoraInicio()))throw new ValidationException("La hora de fin debe ser posterior a la hora de inicio.");}}
